  insert into public.brands (name, website, description, country, status) values ('Perricone MD', 'https://www.perriconemd.com', 'Dermatologist-founded clinical skincare brand (Dr Nicholas Perricone, THG-owned) running its affiliate program through Awin: the Awin profile publishes publisher-type rates including Content & Influencers at 10% on new-customer sales (5% existing) and a dedicated UGC & Communities tier at 8% new / 2% existing, with a 31-day cancellation period; the brand''s own affiliate page confirms ''We work with Awin'' and free joining.', 'United States', 'published') returning id into bid;
