  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/21122?setLocale=pl_PL', 'affiliate_network', 'commission_rate', 'The brand''s Awin US merchant profile publishes standard rates by publisher type: Content & Influencers 10% on new-customer sales and 5% on existing; UGC & Communities 8% new / 2% existing; commissions confirm after a 31-day cancellation period. The recorded 10% is the content/influencer new-customer rate. No earnings-cap statement is published, so commission_cap stays unknown, and no absolute creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 18, 15, 13, 8, 5, '{"niche_fit": "Premium clinical skincare with high order values - ideal for routine, ingredient and results-led UGC.", "ugc_evidence": "The Awin rate card has a dedicated UGC & Communities publisher tier alongside Content & Influencers - the program is explicitly built for creator content.", "compensation": "10% new-customer rate for content/influencer publishers (5% existing); UGC tier 8%/2%. Solid for luxury skincare, though no uncapped statement is published.", "contact_access": "Two published emails: the brand-page affiliate support address and a named Awin contact on the merchant profile.", "opportunity_availability": "Open, free application through Awin with creative assets and promotional offers.", "credibility": "Long-established dermatologist brand owned by THG, with a complete published Awin rate card."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Olive Young', 'https://global.oliveyoung.com', 'CJ Olive Young''s global health & beauty mall runs its own Influencer Program under published terms on its global site: any holder of a social account (YouTube, Facebook, Instagram, TikTok, Twitter/X or Weibo) can apply, approved influencers get a custom Reward Code/Link giving followers 5% off, earn 5-13% of sales as commission points depending on influencer revenue, tracked on a 30-day cookie, convertible to cash via PayPal once points reach USD 20.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct (Olive Young Global Influencer Program)', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://m.global.oliveyoung.com/foot-info/footer-contents?foterSeq=94.', 'https://global.oliveyoung.com', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Olive Young Global Influencer Program', 'https://global.oliveyoung.com', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://m.global.oliveyoung.com/foot-info/footer-contents?foterSeq=94', 'brand_site', 'affiliate_program', 'Olive Young Global''s own Influencer Terms & Conditions (CJ Olive Young Co., Ltd.) govern the program: eligibility requires a social media account, approved members become Influencer Members, create a custom Reward Code automatically included in Reward Links, and sales are counted on a 30-day cookie with last-click attribution.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://m.global.oliveyoung.com/foot-info/footer-contents?foterSeq=94', 'brand_site', 'commission_rate', 'Article 6 of the brand''s own terms: followers get a 5% discount via the Reward Code/Link and the influencer receives 5% - 13% of the sales amount as commission points depending on influencer revenues, with the exact rate designated by separately notified criteria; points post three days after delivery and convert to cash via PayPal at USD 20, withdrawn monthly. Because only a range is published and each member''s rate is set separately, commission_rate is recorded as null. No earnings-cap statement and no absolute creator counts are published, so cap and saturation stay unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 19, 12, 8, 9, 5, '{"niche_fit": "The largest K-beauty catalogue in this batch - endless skincare and makeup material for hauls, routines and reviews.", "ugc_evidence": "A creator-native program: custom reward codes and links for social followers, monthly reliability checks on influencer accounts, and a partnership tier for outstanding performers.", "compensation": "Published 5-13% range depending on revenue, but the per-member rate is set by unpublished criteria, so no single rate can be recorded; PayPal cash-out from USD 20.", "contact_access": "Full program terms published on the brand''s own global site with in-account application; no public program email is published.", "opportunity_availability": "Any social account holder can apply; reapplication is allowed 30 days after a rejection.", "credibility": "Operated by CJ Olive Young, South Korea''s dominant health & beauty retailer, under complete published legal terms."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('DERMAdoctor', 'https://dermadoctor.com', 'US dermatologist-formulated skincare brand founded by Dr Audrey Kunin, with an affiliate program running since 2000: its own affiliate page states it is currently paying 15% of sale on all goods, paid monthly with 30 return days, managed through Shopify Collabs (named on the page as its Affiliate Solutions Manager), free to join with no minimum sales requirement.', 'United States', 'published') returning id into bid;
