  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://dermadoctor.com/pages/affiliate-program', 'brand_site', 'affiliate_program', 'DERMAdoctor''s own affiliate page invites affiliates to join free with no minimum sales requirement, names Shopify Collabs as its Affiliate Solutions Manager, and states ''We are currently paying 15% of sale on all goods, payout monthly and feature 30 return days''; monthly direct deposit and daily sales reporting are described in the page FAQ.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://dermadoctor.com/pages/affiliate-program', 'brand_site', 'commission_cap', 'The brand''s affiliate page publishes no earnings-cap statement and no creator counts, so commission_cap and creator_saturation stay unknown. The page also carries a legacy LinkShare signup reference alongside the current Shopify Collabs management note; the 15% rate and monthly payout are stated in the page''s current wording.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 17, 11, 8, 4, '{"niche_fit": "Problem-solution dermatologist skincare (50+ formulas) - strong before/after and routine UGC material.", "ugc_evidence": "A long-running affiliate program with tracked links, creative assets and daily reporting; no separate creator-content tier is published.", "compensation": "15% on all goods stated on the brand''s own page - one of the higher clean rates this round; cap honestly unknown.", "contact_access": "Published service email and phone number on the affiliate page itself; application is self-serve.", "opportunity_availability": "Free to join, no minimum sales requirement, anyone may apply.", "credibility": "Program running since 2000 under founder Dr Audrey Kunin; the page mixes in a legacy LinkShare reference, so terms should be reconfirmed in the Collabs dashboard."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Dr Sebagh', 'https://www.drsebagh.com', 'London luxury clinical skincare brand whose own Affiliate Programme page (join links route to Awin) offers members a base rate of 10% commission on every confirmed sale with a 30-day cookie, an initial gift of a personalised skincare routine, early access to new products, in-house design assets for content creation, a named social-team point of contact after acceptance, and an annual affiliate event.', 'United Kingdom', 'published') returning id into bid;
