  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 16, 14, 9, 7, 4, '{"niche_fit": "Luxury clinical skincare with premium price points - good economics per sale for skincare creators.", "ugc_evidence": "Programme is pitched at content creators and bloggers with in-house visual materials, product gifting and a social-team contact - a genuine creator route, run through Awin.", "compensation": "Clean published base rate of 10% on confirmed sales with negotiable uplifts; cap unknown.", "contact_access": "Full programme page on the brand''s own domain; a named social-team contact is assigned after acceptance, but no public email is published.", "opportunity_availability": "All interested parties are encouraged to apply, subject to approval; the brand notes high application volume.", "credibility": "Established London clinic brand with complete programme terms on its own site and Awin tracking."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Sunday Riley', 'https://sundayriley.com', 'US clinical skincare brand (Good Genes, C.E.O.) whose affiliate program runs through CJ Affiliate according to network directories; published rate figures conflict across current listings (12% per Lasso and LinkClicky, 10% per LinkApprove, 5-10% per Shopper), so no single rate is recorded. The brand publishes press@ and partnerships@ inboxes for media/influencer and partnership requests.', 'United States', 'published') returning id into bid;
