  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 13, 10, 12, 7, 5, '{"niche_fit": "Hero-product clinical skincare with a huge creator following - among the strongest content fits in this batch.", "ugc_evidence": "Affiliate route exists via CJ plus published influencer/partnership inboxes, but the brand publishes no creator program page of its own.", "compensation": "Directories conflict between 5-10%, 10% and 12%, so no rate is recorded; that uncertainty caps the compensation score.", "contact_access": "Two published inboxes on the brand side - press for influencer requests and partnerships for partnership requests.", "opportunity_availability": "Network application via CJ; brand-side creator contact is email-based rather than a public portal.", "credibility": "Major, long-established skincare brand; the affiliate facts are network-reported rather than brand-published, which is noted in the evidence."}'::jsonb);
