  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 9, 12, 7, 4, '{"niche_fit": "Luxury clean makeup with strong artist-led storytelling - excellent tutorial and complexion UGC material.", "ugc_evidence": "CJ affiliate listing plus a documented ShopMy creator partnership and a published social-collaborations inbox; no brand-run affiliate page.", "compensation": "5% is low for the category and comes from a single network listing; cap unknown.", "contact_access": "Dedicated social-collaborations and press emails published in the brand''s own FAQ.", "opportunity_availability": "Network application via CJ; creator pitches also accepted by email.", "credibility": "Established luxury brand (reported $100M annual net revenue); affiliate terms are network-reported, not brand-published."}'::jsonb);
