  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 20, 15, 14, 7, 8, 3, '{"niche_fit": "Single-category lash specialist - narrow but very focused material for eye-makeup creators.", "ugc_evidence": "The brand''s page explicitly pitches partnering with creators and provides creative assets and promotional offers through ShareASale.", "compensation": "Clean 10% on all sales stated on the brand''s own page; cap unknown.", "contact_access": "No public email; support runs through the dedicated ShareASale program manager after joining.", "opportunity_availability": "Free, open sign-up via ShareASale.", "credibility": "Smaller specialist brand; programme terms are fully published on its own site, but scale is modest."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Bondi Sands', 'https://bondisands.com', 'Australian self-tanning and suncare brand (founded 2012) whose North America affiliate program runs on Impact (merchant #19100 per FMTC''s merchant listing; LinkClicky also records Impact). Published rate figures conflict - LinkClicky lists 10% / 6% dual rates and Shopper lists 5.09% - so no single rate is recorded.', 'Australia', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://linkclicky.com/affiliate-program/bondi-sands/.', null, 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Bondi Sands Affiliate Program (Impact)', null, null, 'unverified', 'ugc');
