  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/bondi-sands/', 'directory', 'commission_rate', 'Rate figures conflict across current listings: LinkClicky lists dual rates of 10% and 6% per sale, InfluencerRate says up to 10%, and Shopper lists 5.09% - no settleable single rate, so commission_rate is null with the conflict documented. No earnings-cap statement or absolute creator counts are published, so cap and saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 14, 10, 6, 8, 4, '{"niche_fit": "Self-tan is one of the most UGC-friendly beauty categories - application, shade and routine content performs well.", "ugc_evidence": "Network affiliate program on Impact for a social-first tanning brand; no brand-published creator page was found.", "compensation": "Conflicting published figures (10%/6% vs 5.09%) mean no rate can be recorded; cap unknown.", "contact_access": "No published program email was found; contact runs through Impact after application.", "opportunity_availability": "Open network application through Impact (North America program).", "credibility": "Established Australian tanning brand founded in 2012 with global retail distribution."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Milk Makeup', 'https://www.milkmakeup.com', 'New York clean, vegan, cruelty-free makeup and skincare brand whose affiliate program runs on Impact (merchant #21499 per FMTC''s merchant listing). The only published rate figure found is a single 1.6% payout on Shopper while other listings describe the rate as varying by partner, so no rate is recorded.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.fmtc.co/fmtc-new-merchants-include-100-thieves-govplus-milk-makeup-rover-and-square-keg/.', null, 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Milk Makeup Affiliate Program (Impact)', null, null, 'unverified', 'ugc');
