  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shopper.com/partnerships/milkmakeup-com-affiliate-program', 'directory', 'commission_rate', 'Shopper''s listing claims a 1.6% payout while Shopday describes the commission as varying by partner with no figure - a single weak figure against unpublished terms, so commission_rate is null. No earnings-cap statement or absolute creator counts are published, so cap and saturation stay unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 8, 6, 7, 4, '{"niche_fit": "Cult clean-beauty brand with highly visual, social-native products - strong makeup UGC fit.", "ugc_evidence": "Affiliate program on a major creator network (Impact); the brand is social-first, though it publishes no creator program page of its own.", "compensation": "No settleable published rate - a lone 1.6% directory figure versus ''varies by partner'' listings; cap unknown.", "contact_access": "No published program email was found; contact runs through Impact after application.", "opportunity_availability": "Application through Impact; approval terms are not published.", "credibility": "Well-known US clean-beauty brand; affiliate facts are network-reported only, which is noted in the evidence."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Heather Robertson', 'https://heatherrobertson.com', 'Home-workout fitness app from trainer Heather Robertson, with structured programs and a large follow-along workout following. Its Community Affiliate Program (run through Rewardful) is built for fitness bloggers, influencers and creators: it pays 25% of net revenue on each referred paid subscription, including renewals for 12 months, and its official FAQ states there is no limit to how much an affiliate can earn.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fitness'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'affiliates@heatherrobertson.com', null, 'https://support.heatherrobertson.com/article/279-affiliate-faqs', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct (Rewardful)', 25, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://support.heatherrobertson.com/article/279-affiliate-faqs.', 'https://support.heatherrobertson.com/article/279-affiliate-faqs', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Heather Robertson Community Affiliate Program', 'https://support.heatherrobertson.com/article/279-affiliate-faqs', 'https://support.heatherrobertson.com/article/279-affiliate-faqs', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://support.heatherrobertson.com/article/279-affiliate-faqs', 'official_program_page', 'commission_cap', 'Official affiliate FAQ, ''How much commission do I earn?'': ''Earn 25% for each paid subscription member you refer. There''s no limit to how much you can earn.'' That is an explicit no-limit earnings statement on the brand''s own support site, so commission_cap is uncapped.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://support.heatherrobertson.com/article/279-affiliate-faqs', 'official_program_page', 'affiliate_program', 'Program mechanics from the official FAQ: commissions are 25% calculated on NET revenue (excluding fees, taxes, refunds, chargebacks and discounts) — recorded as 25 with that basis, not as 25% of sale price. Commissions are also paid on renewals within a 12-month period and on discounted subscriptions (25% of the amount actually paid). Sign-up is through Rewardful, cookies last 60 days, first-touch attribution, commissions payable after 30 days, minimum payout $50 USD, paid via Wise in USD.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://support.heatherrobertson.com/article/279-affiliate-faqs', 'official_program_page', 'creator_program', 'The FAQ defines the program as ''a way for fitness and wellness bloggers, writers, community owners, entrepreneurs, influencers, creators, and others to spread the word'', recommends promoting via Instagram, YouTube, TikTok, blogs, newsletters and private communities, and gives affiliates@heatherrobertson.com for support (1–2 business day response). Restrictions: no paid-media use of the link, no brand keyword bidding, no self-referrals, no incentivised sign-ups.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 17, 18, 13, 9, 4, '{"compensation": "25% of net revenue per referred subscription, paid on renewals for 12 months, with an explicit ''no limit to how much you can earn'' statement on the brand''s own FAQ \u2014 strong, verified-uncapped pay; held below maximum because the rate is on net revenue, not sale price.", "contact_access": "A dedicated affiliates@heatherrobertson.com support email is published in the official FAQ with a stated 1\u20132 business day response time.", "credibility": "Established trainer-led fitness app with a large established workout audience; terms are unusually fully documented, though it is a single-trainer brand rather than a major platform.", "niche_fit": "Home-workout programs are core fitness-creator content, and the app is designed to be promoted through workout and routine content.", "opportunity_availability": "Open sign-up through Rewardful with no follower minimum stated; a few promotion restrictions (no paid media, no brand bidding) apply.", "ugc_evidence": "The program is explicitly built for fitness influencers and creators and names Instagram, YouTube and TikTok promotion as recommended channels."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Bagsmart', 'https://www.bagsmart.com', 'Travel-organisation brand selling packing cubes, toiletry bags, backpacks and luggage accessories designed to make packing systematic. Its affiliate program runs on Awin: the brand''s Awin merchant profile states a flexible base commission with performance boosts up to 10%, and a commission structure headed ''No Cap on Earnings: Unlimited potential for top performers'', with a named affiliate manager and contact email.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'marketingus01@bagsmart.com', null, 'https://ui.awin.com/merchant-profile/28621?setLocale=da_DK', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', null, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://ui.awin.com/merchant-profile/28621?setLocale=da_DK.', 'https://ui.awin.com/merchant-profile/28621?setLocale=da_DK', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Bagsmart Affiliate Program (Awin US)', 'https://ui.awin.com/merchant-profile/28621?setLocale=da_DK', 'https://ui.awin.com/merchant-profile/28621?setLocale=da_DK', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/28621?setLocale=da_DK', 'network_profile', 'commission_cap', 'The brand''s own Awin (US) merchant profile, Commission Structure section: ''Base Commission: Flexible, adjustable commission structure to maximize your earnings. Performance Boost: Earn up to 10% with tiered rewards for high-volume affiliates. No Cap on Earnings: Unlimited potential for top performers.'' The no-cap statement is explicit and appears on the network profile the brand itself maintains, so commission_cap is uncapped. The ''up to 10%'' is a tier ceiling and no fixed base percentage is published, so commission_rate is null.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/28621?setLocale=da_DK', 'network_profile', 'affiliate_program', 'Joining is via the AWIN platform with brand approval; the profile lists promotional resources (banners and creatives, a deeplink generator, exclusive discount codes, a regularly updated product feed and content inspiration such as packing guides), target audiences of travel enthusiasts, backpackers, digital nomads, frequent flyers, commuters and students, and names affiliate manager Lydia Lynn with contact email marketingus01@bagsmart.com.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 13, 16, 12, 8, 4, '{"compensation": "Verified-uncapped on the brand''s own Awin profile (''No Cap on Earnings''); scored below the top because no fixed base rate is published \u2014 only a flexible base with tiered boosts up to a 10% ceiling.", "contact_access": "A named affiliate manager (Lydia Lynn) and a direct email (marketingus01@bagsmart.com) are published on the Awin profile.", "credibility": "Well-known travel-organisation label sold worldwide with strong product reviews, per its Awin profile.", "niche_fit": "Packing and travel-organisation products are a staple of travel-creator content \u2014 packing videos, carry-on guides and gear lists.", "opportunity_availability": "Join through Awin with brand approval; resources and discount codes are provided to approved affiliates.", "ugc_evidence": "The profile supplies content inspiration (travel tips, packing guides, gift ideas) and discount codes for creators, though it is a conventional affiliate program rather than a structured UGC campaign program."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Japan Wireless', 'https://www.japan-wireless.com', 'Japan travel-connectivity company renting pocket Wi-Fi and selling SIM/eSIM products to visitors to Japan. Its own affiliate page invites partners to join its affiliate network, promises ''generous commissions for every referral, with the potential for unlimited earnings'', and provides a dedicated affiliate dashboard after application review — but publishes no commission percentage, so no rate is recorded.', 'Japan', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', null, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://www.japan-wireless.com/en/affiliate?code=013.', 'https://www.japan-wireless.com/en/affiliate?code=013', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Japan Wireless Affiliate Program', 'https://www.japan-wireless.com/en/affiliate?code=013', 'https://www.japan-wireless.com/en/affiliate?code=013', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.japan-wireless.com/en/affiliate?code=013', 'official_program_page', 'commission_cap', 'Official affiliate page, ''Lucrative commissions'': ''Earn generous commissions for every referral, with the potential for unlimited earnings.'' That is an explicit unlimited-earnings statement on the brand''s own page, so commission_cap is uncapped. No percentage rate, cookie or payout terms are published anywhere on the page, so commission_rate is null.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.japan-wireless.com/en/affiliate?code=013', 'official_program_page', 'affiliate_program', 'Mechanics from the official page: partners apply, the brand reviews the application and contacts accepted affiliates directly, and accepted partners get a dedicated affiliate dashboard showing sales and commissions, plus dedicated team support. The page describes Japan Wireless as ''a trusted name in the travel industry in Japan'' and lists a phone contact (+81-50-1807-9771); no affiliate email is published, so no contact row is recorded.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 11, 13, 5, 7, 4, '{"compensation": "Explicit ''potential for unlimited earnings'' wording on the brand''s own affiliate page makes it verified-uncapped, but no commission percentage or payout terms are published at all, so pay cannot be judged higher.", "contact_access": "Only a general phone number is published on the affiliate page \u2014 no partnerships email or named affiliate contact.", "credibility": "An established Japan travel-connectivity provider with a long operating history serving inbound tourists.", "niche_fit": "Pocket Wi-Fi and eSIMs are a practical, frequently recommended product for Japan travel creators and itinerary content.", "opportunity_availability": "Applications are reviewed by the brand before acceptance and dashboard access, which narrows open availability.", "ugc_evidence": "The page pitches passive-income partnerships for travel publishers generally; creator-specific UGC campaigns are not evidenced."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Backcountry', 'https://www.backcountry.com', 'Major US outdoor retailer for ski, climb, hike, camp and travel gear and apparel. Its official Partner Program page offers three tracks: Storyteller (bloggers and gear reviewers, via Impact, 30-day cookie), Creator (Instagram/TikTok/YouTube creators via Popfly, with tracked storefront links, product gifting and paid campaign opportunities) and Community Partner (clubs and groups, via Impact). The official page publishes no commission figure; directories consistently report a sliding 4–12% scale, so the 4% starting tier is recorded.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 4, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.backcountry.com/info/affiliate-program.', 'https://www.backcountry.com/info/affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Backcountry Partner Program (Storyteller / Creator / Community Partner)', 'https://www.backcountry.com/info/affiliate-program', 'https://www.backcountry.com/info/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.backcountry.com/info/affiliate-program', 'official_program_page', 'creator_program', 'Official Partner Program page: three tracks — ''The Storyteller'' (bloggers, gear reviewers, editorial writers; 30-day cookie, banners, text links and product data feed, dedicated program management, apply via Impact), ''The Creator'' (Instagram, TikTok, YouTube, Reels; tracked storefront links plus UTM-ready deep links, product gifting, paid campaign opportunities, first dibs on new drops and creator spotlights, apply via Popfly) and ''The Community Partner'' (clubs, camps, coaches and adventure groups earning commissions via Impact). Every application is reviewed by hand with a reply within five business days. No commission rate or earnings-cap statement is published on the page, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/backcountry/', 'third_party_directory', 'affiliate_program', 'Directories consistently report a sliding commission scale starting at 4% and rising to 12% with volume on a 30-day cookie via Impact (Lasso reports the 4%–12% range; other directories report the same range averaging about 8%). The recorded 4% is the starting tier of that published range.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 18, 11, 7, 8, 5, '{"compensation": "A sliding scale reported consistently as 4% starting, rising to 12% with volume \u2014 a modest starting rate, and the brand''s own page publishes no figure; no cap statement is published.", "contact_access": "Dedicated program management is promised on the official page, but no partnerships email is published \u2014 contact is through the Impact/Popfly applications.", "credibility": "One of the largest and longest-established US outdoor retailers, founded in 1996.", "niche_fit": "Outdoor gear and apparel sits at the centre of travel, adventure and outdoor-fitness creator content.", "opportunity_availability": "Three open application tracks including a dedicated social Creator track, though every application is hand-reviewed (reply within five business days).", "ugc_evidence": "A dedicated Creator track for Instagram, TikTok and YouTube with storefront links, product gifting, paid campaign opportunities and creator spotlights \u2014 strong, explicit UGC evidence."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('HOKA', 'https://www.hoka.com', 'Premium cushioned running-shoe brand (part of Deckers Outdoor) for road, trail and race-day runners. Its official affiliate page states the program offers ''3-14% commissions on all HOKA products sold'' and ''a flat 3-14% commission level through Rakuten Advertising'' on hoka.com sales, free to apply and join, with dedicated affiliate staff, creative and a daily product feed. The recorded 3% is the floor of that published range.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fitness'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Rakuten Advertising', 3, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.hoka.com/en/us/hoka-affiliate-program.html.', 'https://www.hoka.com/en/us/hoka-affiliate-program.html', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'HOKA Affiliate Program (Deckers Outdoor, via Rakuten Advertising)', 'https://www.hoka.com/en/us/hoka-affiliate-program.html', 'https://www.hoka.com/en/us/hoka-affiliate-program.html', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.hoka.com/en/us/hoka-affiliate-program.html', 'official_program_page', 'affiliate_program', 'Official HOKA affiliate page (Deckers Outdoor Affiliate Program): ''We offer 3-14% commissions on all HOKA® products sold'' and ''We offer a flat 3-14% commission level through Rakuten Advertising on all of our products sold through the HOKA.com website. It''s free to apply and join.'' The recorded 3% is the floor of the brand''s own published range. No earnings-cap statement is published, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.hoka.com/en/us/hoka-affiliate-program.html', 'official_program_page', 'affiliate_program', 'The same official page promises a ''healthy partnership with Rakuten Advertising'', dedicated affiliate program staff, fresh creative, performance tracking and reporting, and a product feed updated daily. No affiliate contact email is published on the page.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 12, 13, 7, 9, 5, '{"compensation": "The brand itself publishes a 3\u201314% commission range through Rakuten \u2014 a low floor but a genuinely high ceiling for a premium-price shoe; no cap statement is published.", "contact_access": "Dedicated affiliate program staff are promised on the official page, but no partnerships email is published.", "credibility": "One of the world''s best-known performance running brands, part of Deckers Outdoor.", "niche_fit": "Running shoes are core gear for running and fitness creators, with constant review, rotation and race content.", "opportunity_availability": "Free to apply and join via Rakuten Advertising, open to site owners and publishers.", "ugc_evidence": "The program is a conventional link/feed affiliate program aimed at publishers; creator-specific UGC campaigns are not evidenced on the page."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Free People', 'https://www.freepeople.com', 'Bohemian women''s fashion brand (Urban Outfitters group) covering clothing, intimates, swim and the FP Movement activewear line. Its official affiliates page invites blogs, communities and content sites to add banners and links, with ''an easy sign-up process through Rakuten Advertising'' and commission on all approved sales generated from banners and posts; US directories consistently report 3% with a 14-day cookie, so 3% is recorded.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Rakuten Advertising', 3, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.freepeople.com/uk/help/affiliates/.', 'https://www.freepeople.com/uk/help/affiliates/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Free People Affiliate Program (via Rakuten Advertising)', 'https://www.freepeople.com/uk/help/affiliates/', 'https://www.freepeople.com/uk/help/affiliates/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.freepeople.com/uk/help/affiliates/', 'official_program_page', 'affiliate_program', 'Official Free People affiliates page: ''If you have a blog, community, content site, or other website, you can add a banner or link back to us at FreePeople.com. There''s an easy sign-up process through Rakuten Advertising, or you can connect with us directly if you''re already an established publisher. If you''re approved, all sales generated from your banners and posts will receive a commission.'' The brand publishes no rate or earnings-cap statement on the page, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/free-people/', 'third_party_directory', 'affiliate_program', 'US directories consistently report the Free People program at 3% per sale with a 14-day cookie (Lasso US listing: 3%, 14 days; the UK listing differs at 2.4% with a 1-day cookie). The recorded 3% is the US figure.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 14, 9, 6, 8, 5, '{"compensation": "A low 3% US rate on a short 14-day cookie; the brand publishes no figure itself and no cap statement is published.", "contact_access": "Established publishers can ''connect with us directly'' per the official page, but no partnerships email is published.", "credibility": "A major, long-established women''s fashion brand within the Urban Outfitters group.", "niche_fit": "Boho fashion, outfits and the FP Movement activewear line are heavily covered by fashion and lifestyle creators.", "opportunity_availability": "Easy sign-up through Rakuten Advertising with approval; open to blogs, communities and content sites.", "ugc_evidence": "The official page explicitly recruits outfit-sharing followers, blogs and content sites to post and promote the brand, though the program is link/banner based."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Rumpl', 'https://www.rumpl.com', 'Outdoor blanket brand making technical, recycled-material blankets for camping, road trips and outdoor lounging. Its affiliate program runs on Impact at 8% per sale, and directories describe it as aimed at publishers and influencers promoting through blogs, social media and YouTube; no earnings-cap statement is published, so the cap is honestly unknown.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 8, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://linkclicky.com/affiliate-program/rumpl/.', 'https://linkclicky.com/affiliate-program/rumpl/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Rumpl Affiliate Program (Impact)', 'https://linkclicky.com/affiliate-program/rumpl/', 'https://linkclicky.com/affiliate-program/rumpl/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/rumpl/', 'third_party_directory', 'affiliate_program', 'LinkClicky''s program listing for Rumpl: affiliate platform Impact, commission 8% per sale, all regions, joining via Rumpl''s Impact application; its monetisation section addresses ''publishers and influencers'' promoting across blogs, social media, podcasts and YouTube. Lasso''s directory independently reports the same 8% per sale with a 30-day cookie. No earnings-cap statement is published in either source, so commission_cap is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 12, 13, 4, 8, 4, '{"compensation": "A clean, consistently reported 8% per sale via Impact; no cap statement is published.", "contact_access": "No partnerships email is published in the fetched sources \u2014 joining is through the Impact application.", "credibility": "A well-known outdoor blanket brand with national retail presence and a recycled-materials story, though smaller than the outdoor majors.", "niche_fit": "Camp blankets are a natural fit for camping, vanlife, road-trip and outdoor travel creators.", "opportunity_availability": "Open application through Impact with approval typically within days, per directory guidance.", "ugc_evidence": "Directories frame the program for publishers and influencers on social media and YouTube, but there is no dedicated creator campaign track."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Columbia Sportswear', 'https://www.columbia.com', 'Heritage US outdoor apparel and footwear brand (founded 1938) for hiking, fishing, snow and everyday outdoor wear. Its US affiliate program runs on CJ Affiliate: the brand''s own affiliate page advertises ''up to 10% commissions'' with a 21-day cookie, a complete product data feed and a dedicated affiliate manager — an up-to ceiling, and other published figures conflict, so no base rate is recorded.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'CJ Affiliate', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://marketplace.referly.so/affiliate-programs/columbia-sportswear.', 'https://www.columbia.com/t/affiliates', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Columbia Sportswear Affiliate Program (CJ Affiliate)', 'https://www.columbia.com/t/affiliates', 'https://marketplace.referly.so/affiliate-programs/columbia-sportswear', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://marketplace.referly.so/affiliate-programs/columbia-sportswear', 'third_party_directory', 'affiliate_program', 'Referly''s listing, summarising the terms on Columbia''s own affiliate page (columbia.com/t/affiliates): the US program is managed through CJ Affiliate, pays ''up to 10% commission'' on referred sales with a 21-day cookie window, and offers the largest Columbia selection online, a complete product data feed and exclusive offers on approval; the UK program runs through Impact with up to 10% and a 30-day cookie. ''Up to 10%'' is a ceiling, not a base rate.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.fmtc.co/fmtc-featured-merchant-columbia-sportswear/', 'third_party_directory', 'commission_rate_conflict', 'Published figures conflict: FMTC''s featured-merchant summary says content/influencer partners may receive up to 10% with a 30-day referral window on the CJ-managed US/CA programs, LinkClicky reports 8% per sale via CJ, and Columbia''s program manager Acceleration Partners has referenced up to 15%. Because the brand publishes only an up-to ceiling and sources conflict, commission_rate is null. No earnings-cap statement was found, so commission_cap is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 11, 9, 6, 8, 5, '{"compensation": "Only an ''up to 10%'' ceiling is advertised by the brand and other published figures conflict (8% / up to 15%), so no rate is recorded and compensation scores cautiously; no cap statement is published.", "contact_access": "The brand''s page offers a dedicated affiliate manager contact route, but no partnerships email is published in the fetched sources.", "credibility": "One of the world''s largest outdoor apparel brands, trading since 1938.", "niche_fit": "Outdoor jackets, footwear and fishing/hiking apparel are staples for outdoor, travel and seasonal fashion creators.", "opportunity_availability": "Apply to the CJ program from the brand''s affiliate page and promote on approval; the UK runs separately on Impact.", "ugc_evidence": "FMTC notes content/influencer partners are a recognised publisher type, but the program is primarily a link and data-feed affiliate program."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Sweaty Betty', 'https://www.sweatybetty.com', 'Premium women''s activewear and lifestyle brand founded in Notting Hill, London in 1998. Its affiliate programme runs on Awin: the brand''s Awin merchant profile promises free joining, competitive commission opportunities, strong average order value and increased commission and tailored campaign opportunities for top-performing publishers — but publishes no rate, and directory figures conflict, so no rate is recorded.', 'United Kingdom', 'published') returning id into bid;
