  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://ui.awin.com/merchant-profile/32543.', 'https://ui.awin.com/merchant-profile/32543', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Sweaty Betty Affiliate Programme (Awin)', 'https://ui.awin.com/merchant-profile/32543', 'https://ui.awin.com/merchant-profile/32543', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/32543', 'network_profile', 'affiliate_program', 'The brand''s Awin merchant profile (Sweaty Betty IE): ''Free to join with competitive commission opportunities'', ''Strong average order value and a highly engaged customer base'', regular promotional campaigns and seasonal trading moments, early visibility of launches and offers, and ''Opportunities for increased commission, exclusive partnerships and tailored campaign opportunities for top-performing publishers.'' No percentage or earnings-cap statement is published on the profile, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/sweaty-betty-uk/', 'third_party_directory', 'commission_rate_conflict', 'Directory figures for Sweaty Betty conflict: Lasso reports 2.4% per sale with a 30-day cookie, other directories report up to 8% or up to 12% via Awin. Because the brand''s own Awin profile publishes no figure and sources conflict, commission_rate is null.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 12, 9, 4, 8, 5, '{"compensation": "No rate is published by the brand and directory figures conflict (2.4% / up to 8% / up to 12%), so no rate is recorded and compensation scores low; no cap statement is published.", "contact_access": "No partnerships email is published on the Awin profile \u2014 joining is through the network.", "credibility": "One of the UK''s leading premium women''s activewear brands, founded in 1998.", "niche_fit": "Women''s premium activewear is a core fitness-fashion creator category.", "opportunity_availability": "Free to join via Awin with the brand''s programme open to publishers, with increased-commission opportunities for top performers.", "ugc_evidence": "The Awin profile speaks to publishers and campaign partnerships rather than a structured creator UGC program, though the brand is heavily creator-promoted in practice."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Champion', 'https://www.champion.com', 'Heritage American athleticwear brand founded in 1919 — inventor of the hoodie — selling sportswear, sweats and team apparel. Its affiliate program is administered by Rakuten Advertising: Rakuten''s own Champion store page states affiliates earn a 4% commission on every referred sale, need a website to start, receive banners, and are paid monthly once they reach $25 in earnings, with a 7-day referral window reported by directories.', 'United States', 'published') returning id into bid;
