  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Rakuten Advertising', 4, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.rakuten.com/memorial-day-sale/store/championusa.', 'https://www.rakuten.com/memorial-day-sale/store/championusa', 'needs_review', now());
