  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.rakuten.com/memorial-day-sale/store/championusa', 'third_party_directory', 'affiliate_program', 'Rakuten''s own Champion store page describes the program: ''Champion''s affiliate program allows individuals and businesses to earn a generous 4% commission for every sale they refer to the brand''s online store. All you need to get started as a Champion affiliate is a website... The brand pays out commissions every month to affiliates who have accumulated a minimum of $25 in commission earnings'', with banners provided. Commission Academy''s activewear roundup independently reports the same terms: 4% commission, 7-day referral window, administered by Rakuten Advertising. No earnings-cap statement is published, so commission_cap is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 11, 10, 4, 8, 5, '{"compensation": "A flat 4% published by the network itself, but the 7-day referral window is short, limiting realised earnings; no cap statement is published.", "contact_access": "No partnerships email is published in the fetched sources \u2014 joining is through Rakuten Advertising.", "credibility": "A century-old, world-famous athletic brand with very high recognition.", "niche_fit": "Athletic staples, hoodies and sweats are everyday fitness and streetwear creator content.", "opportunity_availability": "Open to individuals and businesses with a website via Rakuten Advertising, with monthly payouts from a $25 threshold.", "ugc_evidence": "The program is a conventional banner/link affiliate program for websites; creator-specific UGC campaigns are not evidenced."}'::jsonb);
