  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 16, 20, 6, 9, 5, '{"compensation": "40% on every new Zero Plus subscription is the highest percentage rate in this batch; no published cap statement, so the cap is unknown.", "contact_access": "No public partnerships email is published; partners get a dedicated account manager after joining.", "credibility": "20M+ downloads, a 4.8 app rating from 500K+ reviews, and a board-certified Chief Medical Officer.", "niche_fit": "Fasting, protein tracking and metabolic health sit at the centre of the health-creator niche.", "opportunity_availability": "Program is open now, free to join, with an annual-subscription funnel built for payouts.", "ugc_evidence": "The brand runs a dedicated affiliate program explicitly recruiting a growing network of creators and partners."}'::jsonb);
