  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://energybits.com/pages/partners', 'brand_website', 'commission_cap', 'The same official page''s Program Details state ''Earning potential: Unlimited'' and note top affiliates have earned $25,000-$50,000 annually — the explicit unlimited-earnings statement on the brand''s own page is why commission_cap is recorded as uncapped; the page also says it works with thousands of smaller affiliates, so creator_saturation is not low and stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 16, 14, 12, 8, 4, '{"compensation": "10% on all referrals with earning potential stated as unlimited on the brand''s own page, so the cap is verified uncapped.", "contact_access": "The program page publishes a direct affiliates@ email and an interest form.", "credibility": "Long-running algae-nutrition brand, the only algae company it states is endorsed by doctors, nutritionists and pro athletes nationwide, with US third-party lab testing.", "niche_fit": "Algae superfood tablets fit wellness, biohacking and plant-based nutrition creators well.", "opportunity_availability": "Interest form is open now; partners receive free tools, training and a nutritionist contact.", "ugc_evidence": "The brand runs a dedicated ambassador affiliate program and showcases named wellness partners."}'::jsonb);
