  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 15, 18, 6, 8, 3, '{"compensation": "20% recurring commission for life on every referred subscription, with permanent attribution; no published cap statement.", "contact_access": "Application runs through the brand''s own affiliates page; no public partnerships email was found.", "credibility": "Newer, deliberately provocative food-testing service; partner names are prominent but the company itself is young, so credibility is scored conservatively.", "niche_fit": "Food-safety lab data is highly shareable content for health, nutrition and grocery creators.", "opportunity_availability": "Program is open now with a quick application and free Pro access for partners.", "ugc_evidence": "The program is explicitly built for creators and health professionals, with full rights to use its lab data in content."}'::jsonb);
