  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 13, 19, 12, 8, 2, '{"compensation": "Minimum 30% per sale with unlimited commissions stated on the brand''s own page, so the cap is verified uncapped.", "contact_access": "The affiliate page publishes a named email for influencer collabs and a separate support email.", "credibility": "India-based brand whose page leans on individual earnings testimonials; doctor-formulated and clinically tested claims are its own, so credibility is scored low.", "niche_fit": "Ayurvedic men''s-health and wellness formulations fit Ayurveda and natural-health creators, with an India-centred audience.", "opportunity_availability": "Program is open now with no minimum sales requirement; payouts monthly after 5 orders.", "ugc_evidence": "The brand runs its own affiliate program with social, email and site promotion explicitly encouraged."}'::jsonb);
