  insert into public.brands (name, website, description, country, status) values ('Aviya Mattress', 'https://aviyamattress.com', 'US mattress brand selling premium hybrid mattresses that combine pocketed innerspring coils with plant-based cooling foams, direct through AviyaMattress.com, with a 100-night trial and 10-year warranty. Its affiliate program runs on Awin and is pitched at sleep, home-decor and wellness publishers and reviewers.', 'United States', 'published') returning id into bid;
