  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Aviya Mattress Affiliate Program — uncapped payouts per the brand''s Awin profile, 30-day cookie, manager nick@aviyamattress.com', 'https://ui.awin.com/merchant-profile/89261', 'https://ui.awin.com/merchant-profile/89261', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/89261', 'official_site', 'affiliate', 'Aviya''s own Awin merchant profile (the brand''s network program page) fetched in full: headline ''Partner with Aviya Mattress: Premium Hybrid Comfort, Uncapped Earnings'' and the benefits table states ''High Base Commission — Earn competitive, uncapped payouts on every referred sale'', with a 30-day tracking cookie, high average order value, a 4.7/5 rating and a 100-night trial. The explicit uncapped-earnings statements on the brand''s own network profile make the commission cap UNCAPPED. The profile publishes no percentage, so the rate comes from the listing evidence below.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/aviya-mattress/', 'listing', 'affiliate', 'Lasso''s Aviya program listing reports a 10% per-sale commission rate. A Shopper listing separately reports a 10-20% payout range; the 10% figure is the one the dedicated program listing states as the rate, so commission_rate is recorded as 10 with the range noted here.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/89261', 'official_site', 'creator_program', 'The same Awin profile invites review platforms, YouTube review channels and interior-design publications to discuss performance-based tier increases, exclusive audience promo codes and product samples for hands-on testing, and publishes the affiliate manager''s direct email: nick@aviyamattress.com.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 13, 15, 12, 8, 4, '{"niche_fit": "Hybrid mattresses are a core home/sleep UGC review category and Aviya''s innerspring-vs-foam angle gives creators a clear comparison hook", "ugc_evidence": "The program explicitly courts YouTube reviewers and offers product samples for hands-on testing, though it is framed for review publishers rather than social-first creators", "compensation": "Explicit uncapped payouts on the brand''s own network profile plus a reported 10% rate on a high-AOV mattress; tier increases negotiable for top performers", "contact_access": "A named affiliate manager''s direct email (nick@aviyamattress.com) is published on the program profile, plus the Awin application", "opportunity_availability": "Standard Awin application; custom collaborations are aimed at higher-traffic review platforms", "credibility": "Established DTC mattress brand with a 4.7/5 rating and full program terms published on its network profile"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('XGIMI', 'https://us.xgimi.com', 'Global projector brand (10 years in projectors) selling home and portable smart projectors through its official stores, including us.xgimi.com. Its affiliate program is open to forums, bloggers, influencers, reviewers and content creators, who earn commission on every referred sale.', 'United States', 'published') returning id into bid;
