  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'ShareASale', 5, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://global.xgimi.com/pages/affiliate-guide.', 'https://global.xgimi.com/pages/affiliate-guide', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'XGIMI Affiliate Program — ''no cap on commissions'' per official US guide FAQ, 5% per global guide, via ShareASale (Impact/Awin also linked from US store)', 'https://us.xgimi.com/pages/affiliate-guide', 'https://us.xgimi.com/pages/affiliate-guide', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://us.xgimi.com/pages/affiliate-guide', 'official_site', 'affiliate', 'XGIMI''s official US affiliate guide page fetched: the program is open to ''Forums, bloggers, influencers, reviewers, content creators and more'', links to its Impact and Awin program pages, and publishes the program email affiliate@xgimi.com. The page''s FAQ (as indexed from the same official page) states the terms: commission on the product''s official price, a 30-day cookie window, payment 60 days after a successful purchase, monthly payouts, free to join — and answers the earnings question directly: ''There''s no cap on commissions — the more you promote, the more you earn!'' The explicit no-cap statement on the brand''s own page makes the commission cap UNCAPPED.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://global.xgimi.com/pages/affiliate-guide', 'official_site', 'affiliate', 'XGIMI''s official global affiliate guide fetched in full: affiliates register on ShareASale, applications are approved automatically, and the published benefits are ''5% Commission — 5% commission on sales'', a 30-day cookie window, and commission paid within 60 days of a completed order. The 5% rate from the brand''s own guide is the recorded rate; a third-party influencer directory''s ''up to 10%'' claim is not credited over the brand''s own published figure.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 12, 14, 11, 9, 4, '{"niche_fit": "Smart projectors are a highly demonstrable tech product for home-theatre, gaming and room-tour content", "ugc_evidence": "The program explicitly welcomes influencers, reviewers and content creators and supplies banners, coupons and content resources", "compensation": "Explicit ''no cap on commissions'' statement on the brand''s own US page; the rate itself is a modest 5% per the global guide", "contact_access": "Dedicated program email (affiliate@xgimi.com) published on the US guide page, plus network applications", "opportunity_availability": "Applications are approved automatically on ShareASale per the global guide \u2014 the lowest-friction entry in this batch", "credibility": "A decade-old global projector brand with official stores and programs on three major networks"}'::jsonb);
