  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://yogasleep.com/pages/yogasleep-ambassador-program', 'official_site', 'affiliate', 'Official Yogasleep Ambassador Program page fetched in full: affiliates apply through Awin and earn 10% commission on all sound machine sales (Dohm, Dohm Classic and digital multi-sound products) with a 90-day cookie window and monthly payouts through Awin. Mattresses pay a FLAT per-sale commission instead — $65 base per sale, rising with monthly volume bonuses to $90 (11-30 sales), $115 (31-50) and $215 (51+) per sale — a flat bounty structure recorded here, with the 10% sound-machine rate recorded as the percentage rate. The page makes no statement about an earnings cap, so the cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://yogasleep.com/pages/yogasleep-ambassador-program', 'official_site', 'creator_program', 'The same official page is creator-facing throughout: it names parenting and family creators, health and wellness advocates, home and lifestyle reviewers and digital publishers as partner types, offers a media toolkit and brand portal assets, and invites qualified partners to request sample sound machines or mattresses for review via marketing@yogasleep.com.', 'verified', now());
