  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.plushbeds.com/pages/partner-with-us', 'official_site', 'creator_program', 'The same official page runs separate creator routes alongside the affiliate program: a Brand Ambassador Program for influencers and content creators (complimentary products and discounts, social collaboration, no minimum following — ''Your message is more important than the size of your tribe'') and a product-review program sending mattresses to industry experts for honest reviews.', 'verified', now());
