  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Petco Affiliate Program — ~2% base on product sales (up to 10% on services/repeat delivery reported), 7-day cookie, via Impact', 'https://marketplace.referly.so/affiliate-programs/petco', 'https://marketplace.referly.so/affiliate-programs/petco', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://marketplace.referly.so/affiliate-programs/petco', 'listing', 'affiliate', 'Referly''s Petco program profile reports around 2% commission on most products and up to 10% on services and repeat-delivery orders, with a 7-day cookie window, and notes Petco''s own affiliate page at petco.com/affiliate describes joining as free. An independent program index (Affiliate Orchard) likewise records a 2% default on item sale amount under Petco''s public Impact template, excluding gift cards and donations. The recorded rate is the 2% base. No earnings-cap statement is published, so the cap is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://beforeyoubuys.com/best-pet-affiliate-programs/', 'listing', 'affiliate', 'A pet-program roundup reports Petco at 2% to 4% via Rakuten with a 7-day cookie, while other directories cite up to 8%-10% headline figures; the consistent core across sources is a ~2% base rate on product sales with higher rates on services/repeat delivery, recorded here with the variance noted.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 10, 7, 8, 8, 5, '{"niche_fit": "A full-catalogue pet retailer fits almost any pet content \u2014 food, toys, aquatics, small pets \u2014 though it is a retailer rather than a single-product brand", "ugc_evidence": "Publisher program with promotional tools and exclusive offers; no dedicated creator tier verified", "compensation": "A low ~2% base rate and a short 7-day cookie; higher reported rates apply only to services and repeat-delivery orders", "contact_access": "Brand affiliate page (petco.com/affiliate) plus network applications; no public program email found", "opportunity_availability": "Free network application; pet-focused site or channel expected per directory requirements", "credibility": "One of America''s largest pet retailers with 1,500+ stores and a long-established affiliate program"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Chewy', 'https://www.chewy.com', 'Largest US online pet retailer, selling food, supplies, toys and pharmacy products for dogs, cats, horses, reptiles and fish through Chewy.com, known for its Autoship subscription service. It runs an affiliate program through Impact for publishers, alongside a separate Creator Track for social-first creators.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'pets'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://app.impact.com/advertiser-campaign-info/Chewy.brand?lang=en&c=___9XpvYq1Sf08ai2jmVgvAaBi2tdEoZV3N', 'https://www.affiliateorchard.com/programs/chewy/', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 1, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://app.impact.com/advertiser-campaign-info/Chewy.brand?lang=en&c=___9XpvYq1Sf08ai2jmVgvAaBi2tdEoZV3N.', 'https://app.impact.com/advertiser-campaign-info/Chewy.brand?lang=en&c=___9XpvYq1Sf08ai2jmVgvAaBi2tdEoZV3N', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Chewy Affiliate Program — 1% on online sales via Impact (US template), 15-day window, plus a separate Creator Track', 'https://app.impact.com/advertiser-campaign-info/Chewy.brand?lang=en&c=___9XpvYq1Sf08ai2jmVgvAaBi2tdEoZV3N', 'https://app.impact.com/advertiser-campaign-info/Chewy.brand?lang=en&c=___9XpvYq1Sf08ai2jmVgvAaBi2tdEoZV3N', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://app.impact.com/advertiser-campaign-info/Chewy.brand?lang=en&c=___9XpvYq1Sf08ai2jmVgvAaBi2tdEoZV3N', 'listing', 'affiliate', 'Chewy''s own public Impact campaign page states the current US template terms directly: Payout 1% on online sales, a 15-day referral period, and payout scheduling 27 days after the end of the month. An independent index (WhichProgram) records the same 1% / 15-day terms on impact.com, and a program analysis (Affiliate Orchard) confirms the 1% default on item sale amount with pharmacy items, prescription food and treats, and gift cards excluded. No earnings-cap statement is published, so the cap is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.affiliateorchard.com/programs/chewy/', 'listing', 'affiliate', 'Affiliate Orchard''s Chewy profile adds that Chewy directs website/blog publishers to Impact for tracked links while social-first creators are directed to its separate Creator Track, and that the program page conflicts on whether existing-customer orders qualify. Widely quoted 4% figures trace to Chewy Canada''s separate contract and older Partnerize/CJ routes, and one directory''s flat ''$15 per sale'' claim conflicts with the network template — the US Impact template''s 1% is the recorded rate with those conflicts noted here.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 6, 8, 8, 5, '{"niche_fit": "The broadest pet catalogue in the directory \u2014 every species and product type a pet creator covers is sold here", "ugc_evidence": "A separate Creator Track for social-first creators (TikTok, Instagram, YouTube) alongside the publisher program \u2014 a route most retailers do not offer", "compensation": "Only 1% on the US Impact template \u2014 the lowest rate in this batch \u2014 partly offset by very high brand conversion and Autoship repeat orders", "contact_access": "Application through Impact from Chewy''s official program page; no public program email found", "opportunity_availability": "Standard Impact application; affiliate acceptance and promotion methods need confirmation per the program analysis", "credibility": "The largest US online pet retailer, with the program''s current terms published on its own Impact campaign page"}'::jsonb);
